import test from 'node:test';
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import path from 'node:path';
import { analyzeShellCommand, explicitShellEffect, gitPushDanger, scanShell } from '../plugins/v2/shell-guard.mjs';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
// The live permissive rule set, generated by configure.py.
const RULES = JSON.parse(execFileSync('python3', ['-c',
  'import json,configure;print(json.dumps(configure.shell_rules("permissive")))'], { cwd: root, encoding: 'utf8' }));

// Native evaluation matches each parsed command separately; the guard sees the raw string.
const nativeAsks = command => scanShell(command).segments.some(segment => explicitShellEffect(segment.text, RULES)?.effect !== 'allow');
const guardAsks = command => analyzeShellCommand(command, RULES).action !== 'allow';
const asks = command => nativeAsks(command) || guardAsks(command);

const PLAIN = ['git push', 'git push origin main', 'git push -u origin feature/x', 'git push --set-upstream origin my-feature-fix',
  'git push origin HEAD', 'git push origin HEAD:refs/heads/topic', 'git push --tags', 'git push -o ci.skip origin main',
  'git push origin feature-delete-old', 'git -C /home/box/work/yrdsale push origin main', 'git push -n origin main',
  'git fetch && git push origin main', 'cd repo && git push -u origin HEAD', 'timeout 120 git push origin main',
  'env GIT_TERMINAL_PROMPT=0 git push origin main', 'python3 check_receipt.py run -- git push origin main',
  'git push origin main 2>&1 | tail -5', 'git config --get remote.origin.push', 'git log --grep force -5'];

const FORCE = ['git push -f', 'git push -f origin main', 'git push origin main -f', 'git push --force origin main',
  'git push --force-with-lease origin main', 'git push --force-with-lease=main:abc origin main', 'git push origin +main',
  'git push origin +HEAD:main', 'git push origin :old', 'git push --delete origin old', 'git push origin --delete old',
  'git push -d origin old', 'git push --mirror', 'git push --prune origin', 'git push --receive-pack=x origin',
  // Forms native wildcards cannot see; the guard must catch them.
  'git push -uf origin main', 'git push -fu origin main', 'git push origin "+main"', "git push origin ':old'",
  'git -C repo push -f origin main', 'git -c alias.p="push -f" p origin main', 'git -c remote.origin.push=+refs/heads/*:refs/heads/* push',
  '/usr/bin/git push -f origin main', 'git push -- origin +main',
  // Compound and wrapped smuggling.
  'git push origin main && git push -f origin main', 'git status; git push --force', 'true || git push -f',
  'git config remote.origin.push +refs/heads/main:refs/heads/main && git push', 'git config alias.p "push -f"; git p',
  'GIT_CONFIG_COUNT=1 GIT_CONFIG_KEY_0=remote.origin.push GIT_CONFIG_VALUE_0=+main git push',
  'env X=1 git push -f', 'timeout 60 git push --force', 'nohup git push -f origin main', 'echo main | xargs git push -f origin',
  'find . -maxdepth 0 -exec git push -f origin main ;', 'python3 check_receipt.py run -- git push -f origin main',
  'echo $(git push -f origin main)', 'git push origin main > log.txt && git push -f origin main 2>&1 | tail',
  'git reset --hard HEAD~1', 'git rebase main', 'git commit -m x'];

test('plain git push is allowed by both the configure rules and the guard', () => {
  for (const command of PLAIN) {
    assert.equal(nativeAsks(command), false, `rules: ${command}`);
    assert.equal(guardAsks(command), false, `guard: ${command}`);
  }
});

test('force, delete, mirror and smuggled pushes ask', () => {
  for (const command of FORCE) assert.equal(asks(command), true, command);
});

test('configure push asks and the guard classifier agree', () => {
  // Whenever the rules ask for a single git push command, the classifier calls it dangerous too.
  for (const command of [...PLAIN, ...FORCE]) {
    for (const segment of scanShell(command).segments) {
      if (!/^git push\b/.test(segment.text)) continue;
      const ruleAsks = explicitShellEffect(segment.text, RULES)?.effect === 'ask';
      if (ruleAsks) assert.ok(gitPushDanger(segment.words), `rules ask but guard would not: ${segment.text}`);
      else assert.equal(gitPushDanger(segment.words) !== undefined, guardAsks(segment.text), segment.text);
    }
  }
});

test('guard does not double-ask when a configured rule already asks', () => {
  assert.equal(analyzeShellCommand('git push -f origin main', RULES).action, 'allow');
  assert.equal(analyzeShellCommand('git push -uf origin main', RULES).action, 'ask');
  assert.equal(analyzeShellCommand('git push -uf origin main', []).action, 'ask');
});
